{"command":"cd /testbed && /opt/conda/envs/testbed/bin/python -c "
from pgmpy.causal_discovery import PC
import pandas as pd, numpy as np
rng = np.random.default_rng(0)
from pgmpy.independencies import Independencies
from pgmpy.base import DAG
# Graph with a structure where PC stable should differ from orig due to order. Maybe need a graph with multiple CI per round with shared neighbor.
# Let's try random DAGs of 6 nodes and use independence oracle to detect order differences between column orderings.
from itertools import combinations
for seed in range(50):
    np.random.seed(seed)
    nodes = [f'X{i}' for i in range(6)]
    # random DAG
    edges = []
    for i in range(6):
        for j in range(i+1,6):
            if np.random.rand()<0.4:
                edges.append((nodes[i], nodes[j]))
    if not edges: continue
    model = DAG(edges)
    indep = Independencies()
    for u,v in combinations(nodes,2):
        for cond_size in range(0,4):
            for cond in combinations(set(nodes)-{u,v}, cond_size):
                if not model.is_dconnected(u,v,cond):
                    indep.add_assertions((u,v,cond))
    df = pd.DataFrame(np.zeros((100, len(nodes))), columns=nodes)
    try:
        e1=set(tuple(sorted(e)) for e in PC(variant='orig', ci_test='independence_match', show_progress=False, max_cond_vars=4).fit(df, independencies=indep).skeleton_.edges())
        e2=set(tuple(sorted(e)) for e in PC(variant='orig', ci_test='independence_match', show_progress=False, max_cond_vars=4).fit(df.iloc[:,::-1], independencies=indep).skeleton_.edges())
        if e1 != e2:
            print('orig order diff seed', seed)
            print(sorted(e1)); print(sorted(e2))
        e1s=set(tuple(sorted(e)) for e in PC(variant='stable', ci_test='independence_match', show_progress=False, max_cond_vars=4).fit(df, independencies=indep).skeleton_.edges())
        e2s=set(tuple(sorted(e)) for e in PC(variant='stable', ci_test='independence_match', show_progress=False, max_cond_vars=4).fit(df.iloc[:,::-1], independencies=indep).skeleton_.edges())
        if e1s != e2s:
            print('stable order diff seed', seed)
            print(sorted(e1s)); print(sorted(e2s))
    except Exception as e:
        pass
print('done')
"
"}

