    for i in range(7):
        for j in range(i+1,7):
            if np.random.rand()<0.45:
                edges.append((nodes[i], nodes[j]))
    if len(edges)<3: continue
    model = DAG()
    model.add_nodes_from(nodes)
    model.add_edges_from(edges)
    indep = Independencies()
    for u,v in combinations(nodes,2):
