cd /testbed && /opt/conda/envs/testbed/bin/python - <<'PY'
import pandas as pd, numpy as np
from pgmpy.causal_discovery import PC
from pgmpy.tests.test_causal_discovery.test_PC import fake_ci_t, fake_data
fake_df = fake_data.__wrapped__()
import networkx as nx
variables = list(fake_df.columns)
graph = nx.complete_graph(n=variables, create_using=nx.Graph)
lim_neighbors=1
snapshot = {node: set(graph.neighbors(node)) for node in variables}
separating_sets = dict()
removals=[]
# Use a wrapper that reads from snapshot
for u,v in list(graph.edges()):
    for separating_set in get_potential_sepsets(u,v,{},graph,lim_neighbors, snapshot):
        if fake_ci_t(u,v,separating_set):
            separating_sets[frozenset((u,v))]=separating_set
            removals.append((u,v))
            break
print('removals', removals)
for u,v in removals:
    graph.remove_edge(u,v)
print('edges', sorted(graph.edges()))

def get_potential_sepsets(u,v,temporal_ordering,graph,lim_neighbors,neighbor_snapshot=None):
    from itertools import chain, combinations
    if neighbor_snapshot is None:
        sep_u = set(graph.neighbors(u))
        sep_v = set(graph.neighbors(v))
    else:
        sep_u = neighbor_snapshot[u].copy()
        sep_v = neighbor_snapshot[v].copy()
    sep_u.discard(v)
    sep_v.discard(u)
    if temporal_ordering != {}:
        max_order = min(temporal_ordering[u], temporal_ordering[v])
        for neigh in list(sep_u):
            if temporal_ordering[neigh] > max_order:
                sep_u.discard(neigh)
        for neigh in list(sep_v):
            if temporal_ordering[neigh] > max_order:
                sep_v.discard(neigh)
    return chain(combinations(sep_u, lim_neighbors), combinations(sep_v, lim_neighbors))
