from pgmpy.tests.test_causal_discovery.test_PC import fake_ci_t
import networkx as nx
# Stable with snapshot and batch removal should produce union of all edges removable at level 1? Let's simulate for both column orders.
for variables in [['A','B','C','D'], ['D','C','B','A']]:
    graph = nx.complete_graph(n=variables, create_using=nx.Graph)
    lim_neighbors=1
    snapshot = {node: set(graph.neighbors(node)) for node in variables}
    separating_sets={}
    removals=[]
    for u,v in list(graph.edges()):
        sep_u = snapshot[u].copy(); sep_u.discard(v)
        sep_v = snapshot[v].copy(); sep_v.discard(u)
        from itertools import chain, combinations
        for separating_set in chain(combinations(sep_u,lim_neighbors), combinations(sep_v,lim_neighbors)):
            if fake_ci_t(u,v,separating_set):
                separating_sets[frozenset((u,v))]=separating_set
                removals.append((u,v))
                break
    for u,v in removals:
        graph.remove_edge(u,v)
    print(variables, sorted(graph.edges()), separating_sets)
